    'faq_q5' => '<strong>Are there limits on pengguna i tugas?</strong><br>No. Unlimited pengguna, tugas, proyek, i clients. The only limitation is server capacity.',
    'faq_q6' => '<strong>Where is the data stored?</strong><br>100% on your server. The system never syncs data to the cloud.',
